const cutoff = Date.parse('2026-06-01T00:00:00Z');
const eligible = new Set<number>();
const pending = new Set<number>();
let page: number | null = 1;
while (page !== null) {
  const result = await tools.list_issues({repo, state: 'open', label: 'bug', page}) as any;
  for (const issue of result.items) {
    if (issue.state === 'open' && issue.labels.some((label: any) => label.name === 'bug') && issue.milestone === null && Date.parse(issue.updated_at) < cutoff) {
      eligible.add(issue.number);
      if (!issue.labels.some((label: any) => label.name === 'stale')) pending.add(issue.number);
    }
  }
  page = result.next_page ?? null;
}
return {eligibleCount: eligible.size, pending: [...pending]};","answer":""}

